<?php
$search=trim((string)($_GET['search']??''));$department=(int)($_GET['department_id']??0);$status=(string)($_GET['status']??'');$attention=(string)($_GET['attention']??'');
$rows=array_values(array_filter($rows,function($r)use($search,$department,$status,$attention){$s=json_decode($r['snapshot'],true)?:[];$e=$s['employee']??[];return (!$search||stripos(($e['name']??$r['name']).' '.($e['employee_code']??$r['employee_code']),$search)!==false)&&(!$department||(int)($e['department_id']??$r['department_id'])===$department)&&(!$status||pay_simple_stage($r)===$status)&&($attention!=='exceptions'||$r['exceptions']!=='');}));
?>
<div class="pay-heading"><div><span class="eyebrow">EMPLOYEE PAYSLIPS</span><h2><?=h(date('F Y',strtotime($month.'-01')))?></h2><p>Generate, review and publish from this page.</p></div><?php if(can($pdo,$user,'payroll.process.manage')&&(!$run||in_array($run['status'],['Draft','Calculated'],true))){pay_form('pay_generate_simple',['month'=>$month,'version'=>$run['version']??0]);?><button class="button primary"><?=$run?'Regenerate draft payslips':'Generate Payslips'?></button></form><?php endif;?></div>
<form method="get" class="card pay-filters"><input type="hidden" name="page" value="payroll_payslips"><label>Search employee<input name="search" placeholder="Name or employee ID" value="<?=h($search)?>"></label><label>Month<input type="month" name="month" value="<?=h($month)?>" required></label><label>Department<select name="department_id"><option value="">All departments</option><?php foreach($pdo->query('SELECT id,name FROM departments ORDER BY name') as $d):?><option value="<?=$d['id']?>" <?=$department===(int)$d['id']?'selected':''?>><?=h($d['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['Draft','Generated','Finalized','Paid'] as $st):?><option <?=$status===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><button class="button primary">Filter</button></form>
<?php if($attention==='salary'):$q=$pdo->prepare("SELECT e.user_id,u.name,e.employee_code FROM employees e JOIN users u ON u.id=e.user_id WHERE e.deleted_at IS NULL AND e.employment_status='Active' AND u.active=1 AND NOT EXISTS(SELECT 1 FROM hr_salary_assignments s WHERE s.employee_id=e.user_id AND s.effective_from<=? AND (s.effective_to IS NULL OR s.effective_to>=?))");$q->execute([date('Y-m-t',strtotime($month.'-01')),$month.'-01']);?><section class="card"><h2>Missing salary for this month</h2><?php foreach($q as $e):?><p><a href="?page=employee-edit&amp;id=<?=$e['user_id']?>#profile-salary"><?=h($e['name'].' · '.$e['employee_code'])?> → Set salary</a></p><?php endforeach;?></section><?php endif;?>
<?php if($run&&can($pdo,$user,'payroll.process.manage')):?><section class="card pay-month-actions"><div><strong>Month status: <?=h($run['status'])?></strong><p class="pay-muted">Review every employee before finalizing. Published copies become available in employee profiles.</p></div><?php if(in_array($run['status'],['Calculated','Reviewed','Approved'],true)&&can($pdo,$user,'payroll.process.finalize')&&can($pdo,$user,'payroll.process.approve')&&can($pdo,$user,'payslip.generate')):?>
<details><summary class="button">Finalize & publish</summary><?php pay_form('pay_finalize_simple',['month'=>$month,'version'=>$run['version']]);?><label>Review note<input name="reason" required maxlength="1000" placeholder="Payroll reviewed for this month"></label><label class="pay-check"><input type="checkbox" name="confirm" value="1" required>I have reviewed attendance, salary and deductions.</label><button class="button primary">Finalize & publish payslips</button></form></details>
<?php elseif($run['status']==='Finalized'&&can($pdo,$user,'payroll.process.pay')):pay_form('pay_transition',['run_id'=>$run['id'],'version'=>$run['version'],'transition'=>'paid','reason'=>'Payment confirmed by payroll administrator','confirm'=>1]);?><button class="button">Mark month paid</button></form><?php endif;?></section><?php endif;?>
<section class="card pay-panel"><div class="pay-heading"><h2>Payslips <span class="pay-count"><?=count($rows)?></span></h2><span class="pay-muted">Stored monthly calculations</span></div><div class="pay-table"><table><thead><tr><th>Employee</th><th>Employee ID</th><th>Department</th><th>Payroll Month</th><th>Gross Salary</th><th>Attendance Deduction</th><th>Other Deduction</th><th>Net Pay</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r):$s=json_decode($r['snapshot'],true)?:[];$e=$s['employee']??[];$stage=pay_simple_stage($r);$name=$e['name']??$r['name'];$ready=$stage!=='Draft'&&$r['exceptions']==='';?>
<tr><td><strong><?=h($name)?></strong><?php if($r['exceptions']):?><small class="pay-error"><?=nl2br(h($r['exceptions']))?></small><a href="?page=employee-view&amp;id=<?=$r['employee_id']?>&amp;tab=payroll">Review salary</a> · <a href="?page=daily_work_status&amp;employee_id=<?=$r['employee_id']?>&amp;month=<?=h($month)?>">Attendance</a><?php endif;?></td><td><?=h($e['employee_code']??$r['employee_code'])?></td><td><?=h($e['department_name']??'—')?></td><td><?=h($month)?></td><td class="pay-money"><?=pay_amount((int)$r['gross'])?></td><td class="pay-money"><?=pay_amount((int)($s['lop']??0))?></td><td class="pay-money"><?=pay_amount(max(0,(int)$r['deductions']-(int)($s['lop']??0)))?></td><td class="pay-money"><strong><?=pay_amount((int)$r['net'])?></strong></td><td><span class="pay-badge pay-badge-<?=strtolower($stage)?>"><?=$stage?></span></td><td><?php if($ready):?><div class="pay-list-actions"><button class="button" type="button" data-pay-detail="pay-detail-<?=$r['id']?>">View</button><a href="payroll-slip.php?entry=<?=$r['id']?>&amp;download=pdf">PDF</a><a target="_blank" rel="noopener" href="payroll-slip.php?entry=<?=$r['id']?>&amp;print=1">Print</a></div><?php else:?>Resolve exception<?php endif;?></td></tr>
<?php endforeach;if(!$rows):?><tr><td colspan="10"><div class="pay-empty"><strong>No payslips for these filters</strong><p>Choose a month, set employee salaries, then click Generate Payslips.</p></div></td></tr><?php endif;?></tbody></table></div></section>
<?php foreach($rows as $r):$s=json_decode($r['snapshot'],true)?:[];if(pay_simple_stage($r)==='Draft'||$r['exceptions']!=='')continue;$e=$s['employee']??[];?>
<dialog class="pay-detail-drawer" id="pay-detail-<?=$r['id']?>"><div class="pay-heading"><div><span class="eyebrow">PAYSLIP DETAILS</span><h2><?=h($e['name']??$r['name'])?></h2><p><?=h(($e['employee_code']??$r['employee_code']).' · '.($e['department_name']??'').' · '.($e['designation_name']??''))?></p></div><button type="button" class="button" data-pay-close aria-label="Close payslip">×</button></div><div class="pay-metrics"><div><small>Gross</small><strong><?=pay_amount((int)$r['gross'])?></strong></div><div><small>Attendance deduction</small><strong><?=pay_amount((int)($s['lop']??0))?></strong></div><div><small>Other deductions</small><strong><?=pay_amount(max(0,(int)$r['deductions']-(int)($s['lop']??0)))?></strong></div><div><small>Net pay</small><strong><?=pay_amount((int)$r['net'])?></strong></div></div><iframe title="Payslip for <?=h($e['name']??$r['name'])?>" data-src="payroll-slip.php?entry=<?=$r['id']?>" loading="lazy"></iframe><div class="pay-actions"><a class="button primary" href="payroll-slip.php?entry=<?=$r['id']?>&amp;download=pdf">Download PDF</a><a class="button" target="_blank" rel="noopener" href="payroll-slip.php?entry=<?=$r['id']?>">Print / Save PDF</a></div></dialog>
<?php endforeach;?><script src="assets/payroll-four.js" defer></script>
